UPDATE moim_accounts
SET account_status = #{accountStatus}
WHERE moim_account_id = #{moimAccountId}

UPDATE moim_accounts
SET synced_at = CURRENT_TIMESTAMP
WHERE moim_account_id = #{moimAccountId}
  AND user_id = #{userId}

UPDATE moim_accounts
SET account_name = #{accountName},
    updated_at = CURRENT_TIMESTAMP
WHERE moim_account_id = #{moimAccountId}
  AND user_id = #{userId}
  AND account_status = 'ACTIVE'
